import itertools
import json

def solve():
    houses = list(range(5))  # 0..4 representing houses 1..5

    Names = ['Bob', 'Eric', 'Arnold', 'Alice', 'Peter']
    Colors = ['blue', 'green', 'white', 'yellow', 'red']
    Phones = ['huawei p50', 'samsung galaxy s21', 'oneplus 9', 'iphone 13', 'google pixel 6']
    Occupations = ['artist', 'teacher', 'doctor', 'engineer', 'lawyer']

    # Helper to get index of value in an assignment list
    def idx(arr, val):
        return arr.index(val)

    solutions = []

    # Names: Bob is in the second house (index 1)
    other_names = [n for n in Names if n != 'Bob']
    for perm_names in itertools.permutations(other_names):
        names = [None]*5
        names[1] = 'Bob'
        # fill remaining positions (0,2,3,4)
        rem_positions = [0,2,3,4]
        for pos, val in zip(rem_positions, perm_names):
            names[pos] = val

        # Colors: constraints 5 (green != 5th), 7 (blue left of red, adjacent)
        for colors in itertools.permutations(Colors):
            # Clue 5
            if idx(colors, 'green') == 4:
                continue
            # Clue 7: blue directly left of red
            if not (idx(colors, 'red') - idx(colors, 'blue') == 1):
                continue
            # Clue 11: Alice loves yellow
            if idx(names, 'Alice') != idx(colors, 'yellow'):
                continue

            # Phones: constraint 9 (Pixel6 and Huawei P50 separated by one house)
            for phones in itertools.permutations(Phones):
                if abs(idx(phones, 'google pixel 6') - idx(phones, 'huawei p50')) != 2:
                    continue
                # Clue 12: Google Pixel 6 is Eric
                if idx(phones, 'google pixel 6') != idx(names, 'Eric'):
                    continue

                # Occupations: constraint 1 (engineer right of lawyer)
                for occ in itertools.permutations(Occupations):
                    # Clue 1
                    if not (idx(occ, 'engineer') > idx(occ, 'lawyer')):
                        continue
                    # Clue 10: Arnold is engineer
                    if idx(names, 'Arnold') != idx(occ, 'engineer'):
                        continue
                    # Clue 13: Google Pixel 6 is teacher
                    if idx(phones, 'google pixel 6') != idx(occ, 'teacher'):
                        continue
                    # Clue 3: Samsung Galaxy S21 is doctor
                    if idx(phones, 'samsung galaxy s21') != idx(occ, 'doctor'):
                        continue
                    # Clue 4: Doctor loves blue
                    if idx(occ, 'doctor') != idx(colors, 'blue'):
                        continue
                    # Clue 6: Lawyer uses OnePlus 9
                    if idx(occ, 'lawyer') != idx(phones, 'oneplus 9'):
                        continue
                    # Clue 8: Lawyer right of Samsung Galaxy S21
                    if not (idx(occ, 'lawyer') > idx(phones, 'samsung galaxy s21')):
                        continue
                    # Clue 14: Red right of Teacher
                    if not (idx(colors, 'red') > idx(occ, 'teacher')):
                        continue

                    # All constraints satisfied
                    solutions.append((names, colors, phones, occ))

    # Expect unique solution; take the first
    if not solutions:
        raise RuntimeError("No solution found")
    names, colors, phones, occ = solutions[0]

    output = {
        "solution": {
            "header": ["House", "Name", "Color", "PhoneModel", "Occupation"],
            "rows": []
        }
    }
    for i in range(5):
        output["solution"]["rows"].append([
            str(i+1),
            names[i],
            colors[i],
            phones[i],
            occ[i]
        ])

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    solve()
